    "tax_rates.combination_replaces_federal": "Replaces the federal rate",
    "tax_rates.combination_stacks_on_federal": "Stacks on the federal rate",
    "tax_rates.combination_compounds_on_federal": "Compounds on the federal rate",
    "tax_rates.combination_federal": "Federal rate",
